INSERT OR REPLACE INTO _catalog (name, product_id, external, description, product_question, tests, time_axis, columns, row_count, serving_status, publication_id, source_run_id, published_bytes, freshness, exported_at) VALUES ('gold_culture_calendar_density', 'culture_calendar_density', 1, '일×구 문화 밀도·경쟁 지수(#269). 시민 "볼 게 많은 날"=total_events, 주최자 "피해야 할 날"=concentration. int_culture_activity_days 재사용 — location_daily가 유형별 count면 여기는 다양성·집중도 요약. 그레인 gu_code×event_date.', '구별로 어느 날짜에 행사가 몰리나(밀집도)?', '["not_null(event_date)", "not_null(gu_code)", "unique_combination_of_columns"]', 'event_date', '[{"name": "gu_code", "type": "TEXT"}, {"name": "gu", "type": "TEXT"}, {"name": "event_date", "type": "TEXT"}, {"name": "total_events", "type": "INTEGER"}, {"name": "distinct_types", "type": "INTEGER"}, {"name": "busiest_type", "type": "TEXT"}, {"name": "busiest_type_count", "type": "INTEGER"}, {"name": "concentration", "type": "REAL"}]', 67579, 'published', 'local-fixture', 'local-fixture', 0, '2027-05-30', '2026-08-04T04:06:40.103769+00:00');
